import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';

function isValidDiscount(discount) {
  if (discount === undefined || discount === null) return true;
  if (typeof discount !== 'number') return false;
  return discount >= 0 && discount <= 100;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  if (!lines || lines.length === 0) return fail('NO_LINES');

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    if (!isValidDiscount(line.discountPercent)) return fail('DISCOUNT_INVALID');

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: line.discountPercent ?? 0,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total for a single line: qty * unitPrice.
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number} total in cents
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent: number }> }}
 * @returns {{ subtotal: number, discount: number, total: number }} amounts in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = roundCents(invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0));

  const discount = roundCents(
    invoice.lines.reduce((sum, line) => {
      const discountPercent = line.discountPercent ?? 0;
      const lineDiscount = roundCents(lineTotal(line) * (discountPercent / 100));
      return sum + lineDiscount;
    }, 0)
  );

  const total = Math.max(0, subtotal - discount);

  return {
    subtotal,
    discount,
    total,
  };
}

/**
 * Add a line to an invoice or increase qty if the SKU already exists.
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent: number }} line
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  if (!isValidDiscount(discountPercent)) return fail('DISCOUNT_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex !== -1) {
    newLines[existingLineIndex].qty += qty;
    if (discountPercent !== undefined && discountPercent !== null) {
      newLines[existingLineIndex].discountPercent = discountPercent;
    }
  } else {
    const product = productResult.value;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discountPercent ?? 0,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue an invoice, assigning it a number and changing status to 'issued'.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - array of invoice numbers already used
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

function isValidDate(dateStr) {
  if (typeof dateStr !== 'string') return false;
  const match = /^\d{4}-\d{2}-\d{2}$/.exec(dateStr);
  if (!match) return false;
  const date = new Date(dateStr + 'T00:00:00Z');
  return date instanceof Date && !isNaN(date) && date.toISOString().startsWith(dateStr);
}

